Here is a C++ function that takes a reference to a `std::string` containing markdown formatted text and returns a `std::string` containing HTML formatted text:

```cpp
#include <iostream>
#include <string>
#include <sstream>

std::string markdownToHtml(const std::string& markdown) {
    // Code: convert markdown to HTML
    std::string html;
    std::istringstream stream(markdown);
    std::string line;
    while (std::getline(stream, line)) {
        html += line + "<br>";
    }
    return html;
}

int main() {
    std::string markdown = "# Example\n\nThis is a test paragraph.\n\nThis is a second paragraph.";
    std::string html = markdownToHtml(markdown);
    std::cout << html << std::endl;
    return 0;
}
```

